/*
 * MouseTrail Themes gallery.
 *
 * Self-contained, no external requests other than fetching ./themes.json
 * (generated by ../scripts/build_index.py) and the "Add to MouseTrail" /
 * "Download .json" links, which point at this repo's own raw file URLs.
 * No CDNs, no fonts, no analytics, no download counters.
 */

(function () {
  "use strict";

  var STRINGS = {
    en: {
      siteTitle: "MouseTrail Themes",
      tagline: "A public gallery of gradient trail themes for MouseTrail.",
      filterAll: "All",
      filterDesigner: "Designer",
      filterNeon: "Neon",
      filterCommunity: "Community",
      badgeDesigner: "Designer",
      badgeNeon: "Neon",
      badgeCommunity: "Community",
      addButton: "Add to MouseTrail",
      downloadButton: "Download .json",
      addDisabledTitle: "available on the published site",
      localPreviewNote:
        'This is a local preview. "Add to MouseTrail" links only resolve on the published site.',
      emptyState: "No themes in this collection yet.",
      licenseNote: "Themes licensed CC BY-NC 4.0",
      licenseLink: "LICENSE",
      footerSub:
        "No download counters. No analytics. No external requests besides theme data.",
      rainbowLabel: "rainbow (animated)",
      loadError: "Could not load themes.json.",
    },
    zh: {
      siteTitle: "MouseTrail 主题库",
      tagline: "MouseTrail 渐变轨迹主题的公开展示库。",
      filterAll: "全部",
      filterDesigner: "设计师精选",
      filterNeon: "霓虹",
      filterCommunity: "社区",
      badgeDesigner: "设计师精选",
      badgeNeon: "霓虹",
      badgeCommunity: "社区",
      addButton: "添加到 MouseTrail",
      downloadButton: "下载 .json",
      addDisabledTitle: "仅在已发布的网站上可用",
      localPreviewNote:
        "这是本地预览。“添加到 MouseTrail”链接仅在已发布的网站上可用。",
      emptyState: "该分类下暂时还没有主题。",
      licenseNote: "主题采用 CC BY-NC 4.0 许可协议",
      licenseLink: "许可协议",
      footerSub: "没有下载计数，没有数据分析，除主题数据外不发起任何外部请求。",
      rainbowLabel: "彩虹（动态）",
      loadError: "无法加载 themes.json。",
    },
  };

  var LANG_STORAGE_KEY = "mousetrail-themes-lang";

  var state = {
    lang: loadLang(),
    collection: "all",
    themes: [],
  };

  function loadLang() {
    try {
      var stored = window.localStorage.getItem(LANG_STORAGE_KEY);
      if (stored === "en" || stored === "zh") return stored;
    } catch (err) {
      /* localStorage unavailable (e.g. private mode) -- fall back below */
    }
    return "en";
  }

  function saveLang(lang) {
    try {
      window.localStorage.setItem(LANG_STORAGE_KEY, lang);
    } catch (err) {
      /* ignore -- language choice just won't persist */
    }
  }

  function t(key) {
    var table = STRINGS[state.lang] || STRINGS.en;
    return table[key] || STRINGS.en[key] || key;
  }

  // ---- Raw-URL derivation -------------------------------------------------
  //
  // The site is served from docs/ as the Pages root, so a relative link to
  // ../themes/... does not resolve on the published site. Instead we derive
  // the raw.githubusercontent.com URL for the theme file at runtime from the
  // page's own hostname/path -- nothing here hardcodes an owner or repo
  // name, so the same code works no matter who publishes this repo.

  function publishedRepoInfo() {
    var host = window.location.hostname || "";
    if (!host.endsWith(".github.io")) return null;

    var owner = host.split(".")[0];
    var segments = window.location.pathname.split("/").filter(Boolean);
    var repo = segments[0];
    if (!owner || !repo) return null;

    return { owner: owner, repo: repo };
  }

  function rawUrlFor(themePath) {
    var info = publishedRepoInfo();
    if (!info) return null;
    return (
      "https://raw.githubusercontent.com/" +
      info.owner +
      "/" +
      info.repo +
      "/main/" +
      themePath
    );
  }

  function isPublished() {
    return publishedRepoInfo() !== null;
  }

  // ---- Color helpers -------------------------------------------------------

  function toByte(component) {
    var clamped = Math.max(0, Math.min(1, Number(component) || 0));
    return Math.round(clamped * 255);
  }

  function toHex(stop) {
    var r = toByte(stop.red).toString(16).padStart(2, "0");
    var g = toByte(stop.green).toString(16).padStart(2, "0");
    var b = toByte(stop.blue).toString(16).padStart(2, "0");
    return "#" + (r + g + b).toUpperCase();
  }

  function toCss(stop) {
    var r = toByte(stop.red);
    var g = toByte(stop.green);
    var b = toByte(stop.blue);
    var a = Math.max(0, Math.min(1, Number(stop.alpha)));
    if (isNaN(a)) a = 1;
    return "rgba(" + r + "," + g + "," + b + "," + a + ")";
  }

  function gradientCss(stops) {
    if (!stops || stops.length === 0) {
      return "linear-gradient(90deg, #ccc, #eee)";
    }
    var sorted = stops.slice().sort(function (a, b) {
      return (a.location || 0) - (b.location || 0);
    });
    var stopList = sorted
      .map(function (stop) {
        var pct = Math.max(0, Math.min(1, Number(stop.location) || 0)) * 100;
        return toCss(stop) + " " + pct.toFixed(2) + "%";
      })
      .join(", ");
    return "linear-gradient(90deg, " + stopList + ")";
  }

  // ---- Rendering -------------------------------------------------------

  function badgeKey(collection) {
    if (collection === "designer") return "badgeDesigner";
    if (collection === "neon") return "badgeNeon";
    return "badgeCommunity";
  }

  function buildCard(theme, template) {
    var node = template.content.firstElementChild.cloneNode(true);

    node.querySelector(".card-swatch").style.background = gradientCss(theme.stops);
    node.querySelector(".card-name").textContent = theme.name;
    if (theme.author) {
      var authorEl = document.createElement("span");
      authorEl.className = "card-author";
      authorEl.textContent = "@" + theme.author;
      node.querySelector(".card-name").appendChild(document.createTextNode(" "));
      node.querySelector(".card-name").appendChild(authorEl);
    }

    var badge = node.querySelector(".badge");
    badge.textContent = t(badgeKey(theme.collection));

    var chipRow = node.querySelector(".chip-row");
    if (theme.rainbow) {
      var chip = document.createElement("span");
      chip.className = "chip";
      chip.textContent = t("rainbowLabel");
      chipRow.appendChild(chip);
    } else {
      var sortedStops = (theme.stops || [])
        .slice()
        .sort(function (a, b) {
          return (a.location || 0) - (b.location || 0);
        });
      sortedStops.forEach(function (stop) {
        var chipEl = document.createElement("span");
        chipEl.className = "chip";
        var dot = document.createElement("span");
        dot.className = "chip-swatch";
        dot.style.background = toCss(stop);
        chipEl.appendChild(dot);
        chipEl.appendChild(document.createTextNode(toHex(stop)));
        chipRow.appendChild(chipEl);
      });
    }

    var addBtn = node.querySelector(".btn-add");
    var downloadBtn = node.querySelector(".btn-download");
    var raw = rawUrlFor(theme.path);

    if (raw) {
      addBtn.href =
        "mousetrail://import?url=" + encodeURIComponent(raw);
      addBtn.removeAttribute("aria-disabled");
      addBtn.removeAttribute("title");
      downloadBtn.href = raw;
    } else {
      addBtn.href = "#";
      addBtn.setAttribute("aria-disabled", "true");
      addBtn.title = t("addDisabledTitle");
      addBtn.addEventListener("click", function (event) {
        event.preventDefault();
      });
      // Local preview fallback: docs/ is not the server root when previewing
      // with `python3 -m http.server` from the repo root, so a relative link
      // back up to themes/ resolves correctly.
      downloadBtn.href = "../" + theme.path;
    }
    addBtn.textContent = t("addButton");
    downloadBtn.textContent = t("downloadButton");
    // Explicit filename: with a bare `download` attribute some browsers save
    // the file without its .json extension; naming it from the theme path
    // guarantees e.g. "matcha.json".
    downloadBtn.setAttribute("download", theme.path.split("/").pop());

    return node;
  }

  function render() {
    document.documentElement.lang = state.lang === "zh" ? "zh-Hans" : "en";

    document.querySelectorAll("[data-i18n]").forEach(function (el) {
      el.textContent = t(el.getAttribute("data-i18n"));
    });

    document.querySelectorAll(".filter-tab").forEach(function (tab) {
      tab.classList.toggle(
        "is-active",
        tab.getAttribute("data-collection") === state.collection
      );
    });

    var localNote = document.getElementById("local-preview-note");
    localNote.hidden = isPublished();

    var gallery = document.getElementById("gallery");
    var emptyState = document.getElementById("empty-state");
    var template = document.getElementById("card-template");

    gallery.innerHTML = "";

    var visible = state.themes.filter(function (theme) {
      return state.collection === "all" || theme.collection === state.collection;
    });

    emptyState.hidden = visible.length !== 0;

    visible.forEach(function (theme) {
      gallery.appendChild(buildCard(theme, template));
    });
  }

  function init() {
    document.getElementById("lang-toggle").addEventListener("click", function () {
      state.lang = state.lang === "en" ? "zh" : "en";
      saveLang(state.lang);
      render();
    });

    document.getElementById("filters").addEventListener("click", function (event) {
      var tab = event.target.closest(".filter-tab");
      if (!tab) return;
      state.collection = tab.getAttribute("data-collection");
      render();
    });

    fetch("themes.json")
      .then(function (response) {
        if (!response.ok) throw new Error("HTTP " + response.status);
        return response.json();
      })
      .then(function (data) {
        state.themes = data.themes || [];
        render();
      })
      .catch(function (err) {
        var gallery = document.getElementById("gallery");
        gallery.textContent = t("loadError") + " (" + err.message + ")";
      });

    render();
  }

  document.addEventListener("DOMContentLoaded", init);
})();
